from pathlib import Path
import gzip, hashlib, json
P=Path(__file__).resolve().parent; client=P.parents[3]
def perm(n):
    n&=0xffffffff;n^=n>>16;n=n*0x85ebca6b&0xffffffff;n^=n>>13;n=n*0xc2b2ae35&0xffffffff;return(n^(n>>16))&0xffffffff
def expansion(n):return [(n+i)&0xffffffff for i in range(32)]+[perm(n+i) for i in range(32)]
cases=json.loads((P/'cases.json').read_text())
preimages=[s for t in cases for s in [t['seed'],t['setup'],t['reverseSetup'],*t['evalFutures']]]
queries={v for n in preimages for v in expansion(n)}
assert len(cases)==108 and len(preimages)==540 and len(queries)==34560
reserved=json.loads((P/'reserved-scanned-preimages.json').read_text())
assert all(s in reserved for s in preimages)
blocked=set();verified=[]
def collect(o):
    if isinstance(o,bool):return
    if isinstance(o,int):
        if o in queries:blocked.add(o)
    elif isinstance(o,list):
        for v in o:collect(v)
    elif isinstance(o,dict):
        for k,v in o.items():
            if k=='reservedScannedPreimages':
                for n in v:
                    blocked.update(set(expansion(n))&queries)
            collect(v)
for name,expected in json.loads((P/'exclusion-ledgers.json').read_text()).items():
    if name.startswith('derived:'):
        namespace=name[len('derived:'):]
        for i in range(1,int(expected)+1):
            n=int.from_bytes(hashlib.sha256(f'{namespace}:{i}'.encode()).digest()[:4],'little')
            blocked.update(set(expansion(n))&queries)
        verified.append(name);continue
    raw=(client/name).read_bytes()
    if hashlib.sha256(raw).hexdigest()!=expected:
        preserved=P/'ledger-preserved'/Path(name).name
        assert preserved.exists(),name
        raw=preserved.read_bytes()
    assert hashlib.sha256(raw).hexdigest()==expected,name
    collect(json.loads(gzip.decompress(raw) if name.endswith('.gz') else raw))
    verified.append(name)
assert not blocked,sorted(blocked)
result={'qualityPassed':True,'families':108,'distinctUsedPreimages':540,'distinctUsedRawAndPermutedChannels':34560,'verifiedLedgersIncludingDerived':len(verified),'priorIntersections':0,'allPreimagesReserved':True}
with(P/'independent-seed-verification.json').open('x')as f:json.dump(result,f,indent=2);f.write('\n')
print(json.dumps(result))
